.mantle-wrapper {
  display: flex;
  flex-direction: column;
  align-items: center;
  position: relative;
  cursor: pointer;
}
.mantle-svg {
  width: 90px;
  height: 98px;
  transition: transform 0.2s, filter 0.2s;
  filter: drop-shadow(0 2px 6px rgba(0,0,0,0.08));
}
.mantle-svg.hovered {
  transform: scale(1.05);
  filter: drop-shadow(0 4px 12px rgba(0,0,0,0.12));
}
.mantle-svg.on {
  filter: drop-shadow(0 0 15px rgba(239,68,68,0.3));
}
.glow {
  animation: mantleGlow 2s ease infinite alternate;
}
@keyframes mantleGlow {
  0% { opacity: 0.1; }
  100% { opacity: 0.25; }
}
.mantle-label {
  position: absolute;
  bottom: -2px;
  font-size: 0.6rem;
  font-weight: 700;
  padding: 1px 6px;
  border-radius: 6px;
  white-space: nowrap;
  pointer-events: none;
}
.mantle-label.on {
  color: #ea580c;
  background: rgba(254,243,199,0.9);
}
.mantle-label.off {
  color: #64748b;
  background: rgba(241,245,249,0.9);
}

